it('c.redirect() w/ raw CR and LF', () => {
  let res = c.redirect('/destination\r\nSet-Cookie: foo=bar')
  expect(res.headers.get('Location')).toBe('/destination%0D%0ASet-Cookie: foo=bar')

  res = c.redirect('/destination\rSet-Cookie: foo=bar')
  expect(res.headers.get('Location')).toBe('/destination%0DSet-Cookie: foo=bar')

  res = c.redirect('/destination\nSet-Cookie: foo=bar')
  expect(res.headers.get('Location')).toBe('/destination%0ASet-Cookie: foo=bar')
})

it('c.redirect() w/ percent-encoded CR and LF', () => {
  const res = c.redirect('/destination%0D%0ASet-Cookie:%20foo=bar')
  expect(res.headers.get('Location')).toBe('/destination%0D%0ASet-Cookie:%20foo=bar')
})

